80	{
81	  repoRoot?: string;
82	  loadConfig?: typeof LoadRealtimeAgentConfig;
83	  loadApiKey?: typeof LoadOpenAiApiKey;
84	  createRuntimeLogger?: typeof CreateRuntimeLogger;
85	  listInputDevices?: typeof ListInputDevices;
