107	export function ParseCliArgs(argv: string[]): ParseCliResult
108	{
109	  const { values } = parseArgs({
110	    args: argv.slice(2),
111	    options: {
112	      "prompt-file": { type: "string" },
113	      "context-file": { type: "string" },
114	      model: { type: "string" },
115	      tool: { type: "string", multiple: true },
116	      "input-device": { type: "string" },
117	      "list-input-devices": { type: "boolean", default: false },
118	      "safety-identifier": { type: "string" },
119	    },
120	    allowPositionals: false,
121	  });
122	
123	  if (values["list-input-devices"] === true)
124	  {
125	    return { action: "list_input_devices" };
126	  }
127	
128	  const contextFile = values["context-file"];
129	  if (contextFile === undefined || contextFile.trim().length === 0)
130	  {
131	    throw new CliUsageError("--context-file is required.");
132	  }
133	
134	  const rawTools = values.tool;
135	  const toolValues = rawTools === undefined ? [] : Array.isArray(rawTools) ? rawTools : [rawTools];
136	  const promptFile = values["prompt-file"];
