159	    promptFile: options.promptFile ?? config.defaultPromptPath,
160	    contextFile: options.contextFile,
161	    model: options.model ?? config.model,
162	    toolNames: options.toolNames,
163	    inputDevice: options.inputDevice,
164	    safetyIdentifier: options.safetyIdentifier,
