177	export async function StartCliRuntime(
178	  options: ResolvedCliRunOptions,
179	  deps: CliRunDeps & {
180	    apiKey: string;
181	    agentConfig: ResolvedRealtimeAgentConfig;
182	    runtimeLogger: RuntimeLogger;
183	  },
184	): Promise<CliRuntime>
185	{
186	  const apiKey = deps.apiKey;
187	  const runtimeLogger = deps.runtimeLogger;
188	  const agentConfig = deps.agentConfig;
189	
190	  runtimeLogger.Log("cli_startup", {
191	    model: options.model,
192	    turn_mode: x_defaultTurnMode.type,
193	    prompt_file: options.promptFile,
194	    context_file: options.contextFile,
195	  });
196	
197	  const unknownTools = FindUnknownToolNames(options.toolNames);
198	  if (unknownTools.length > 0)
199	  {
200	    throw new CliUsageError(`Unknown tool(s): ${unknownTools.join(", ")}`);
201	  }
202	
203	  let systemPrompt: string;
204	  let initialContext: string;
205	
206	  try
207	  {
208	    systemPrompt = await readFile(options.promptFile, "utf8");
209	  }
210	  catch (error)
211	  {
212	    const message = error instanceof Error ? error.message : String(error);
213	    runtimeLogger.LogError("prompt_load_failed", {
214	      prompt_file: options.promptFile,
215	      error: message,
216	    });
217	    throw error;
218	  }
219	
220	  try
221	  {
222	    initialContext = await readFile(options.contextFile, "utf8");
223	  }
224	  catch (error)
225	  {
226	    const message = error instanceof Error ? error.message : String(error);
227	    runtimeLogger.LogError("context_load_failed", {
228	      context_file: options.contextFile,
229	      error: message,
230	    });
231	    throw error;
232	  }
233	
234	  let database: RealtimeAgentDb;
235	  try
236	  {
237	    database = (deps.createDatabase ?? ((config) =>
238	      RealtimeAgentDb.open({ path: config.databasePath })))(agentConfig);
239	  }
240	  catch (error)
241	  {
242	    const message = error instanceof Error ? error.message : String(error);
243	    runtimeLogger.LogError("persistence_init_failed", {
244	      database_path: agentConfig.databasePath,
245	      error: message,
246	    });
247	    throw error;
248	  }
249	
250	  const startSession = deps.startSession ?? startAgentSession;
251	  const createCapture = deps.createMicrophoneCapture ?? CreateMicrophoneCapture;
252	
253	  let session: RealtimeAgentSession | undefined;
254	  let audioCapture: MicrophoneCapture | undefined;
255	  let shuttingDown = false;
256	
257	  const shutdown = async (reason: string, code: number): Promise<number> =>
258	  {
259	    if (shuttingDown)
260	    {
261	      return code;
262	    }
263	
264	    shuttingDown = true;
265	    audioCapture?.stop();
266	
267	    if (session !== undefined)
268	    {
269	      try
270	      {
271	        await session.stop(reason);
272	      }
273	      catch (stopError)
274	      {
275	        const message =
276	          stopError instanceof Error ? stopError.message : String(stopError);
277	        console.error(`Failed to stop session: ${message}`);
278	        runtimeLogger.LogError("session_stop_failed", { reason, error: message });
279	      }
280	    }
281	
282	    database.close();
283	    runtimeLogger.Log("cli_shutdown", { reason, exit_code: code });
284	    runtimeLogger.Close();
285	    return code;
286	  };
287	
288	  const agentStartConfig: AgentStartConfig = {
289	    systemPrompt,
290	    initialContext,
291	    toolCallSet: BuildToolCallSet(options.toolNames),
292	    model: options.model,
293	    turnMode: x_defaultTurnMode,
294	    onEvent: (event, info) =>
295	    {
296	      logEventLine({
297	        sessionId: info.sessionId,
298	        direction: info.direction,
299	        event,
300	      });
301	    },
302	    onSessionEnded: (info) =>
303	    {
304	      runtimeLogger.Log("realtime_session_ended", {
305	        session_id: info.sessionId,
306	        reason: info.reason,
307	      });
308	
309	      if (info.reason === x_connectionLostReason)
310	      {
311	        console.error("Realtime connection lost; session ended.");
312	        runtimeLogger.LogError("realtime_connection_lost", {
313	          session_id: info.sessionId,
314	        });
315	        void shutdown(info.reason, 1).then((exitCode) =>
316	        {
317	          if (deps.registerSignalHandlers !== false)
318	          {
319	            process.exit(exitCode);
320	          }
321	        });
322	      }
323	    },
324	    onToolLifecycle: (notification) =>
325	    {
326	      if (notification.phase === "failed")
327	      {
328	        runtimeLogger.LogError("tool_dispatch_failed", {
329	          session_id: notification.sessionId,
330	          tool_call_id: notification.toolCallId,
331	          tool_name: notification.toolName,
332	          error: notification.error,
333	        });
334	      }
335	    },
336	  };
337	
338	  try
339	  {
340	    const sessionDeps: AgentSessionDeps = {
341	      apiKey,
342	      safetyIdentifier: options.safetyIdentifier,
343	      database,
344	      ...deps.sessionDeps,
345	    };
346	
347	    runtimeLogger.Log("realtime_connecting", { model: options.model });
348	    session = await startSession(agentStartConfig, sessionDeps);
349	    runtimeLogger.Log("realtime_connected", { session_id: session.sessionId });
350	  }
351	  catch (error)
352	  {
353	    database.close();
354	
355	    if (error instanceof RealtimeTransportError)
356	    {
357	      runtimeLogger.LogError("realtime_connection_failed", {
358	        error: error.message,
359	      });
360	      runtimeLogger.Close();
361	      throw error;
362	    }
363	
364	    const message = error instanceof Error ? error.message : String(error);
365	    runtimeLogger.LogError("realtime_session_start_failed", { error: message });
366	    runtimeLogger.Close();
367	    throw new Error(`Failed to start realtime session: ${message}`);
368	  }
369	
370	  try
371	  {
372	    audioCapture = createCapture({
373	      inputDevice: options.inputDevice,
374	      onFrame: (pcmBase64) =>
375	      {
376	        session?.sendAudioFrame(pcmBase64);
377	      },
378	      onError: (captureError) =>
379	      {
380	        console.error(`Microphone capture failed: ${captureError.message}`);
381	        runtimeLogger.LogError("microphone_capture_failed", {
382	          error: captureError.message,
383	        });
384	        void shutdown("audio_error", 1).then((exitCode) =>
385	        {
386	          if (deps.registerSignalHandlers !== false)
387	          {
388	            process.exit(exitCode);
389	          }
390	        });
391	      },
392	    });
393	    audioCapture.start();
394	    runtimeLogger.Log("microphone_started", {
395	      input_device: options.inputDevice,
396	    });
397	  }
398	  catch (error)
399	  {
400	    const message = error instanceof Error ? error.message : String(error);
401	    runtimeLogger.LogError("microphone_setup_failed", { error: message });
402	    await shutdown("audio_setup_error", 1);
403	    throw error;
404	  }
405	
406	  return {
407	    session,
408	    audioCapture,
409	    database,
410	    runtimeLogger,
411	    shutdown,
412	  };
413	}
